window.ScripturaLexicons.BDAG_PART_0014 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haima-bdag\" data-source=\"BDAG\" data-search=\"αἷμα haima sangue vida sangue Cristo expiação cor vermelha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἷμα</td><td>Substantivo</td><td>sangue; sangue vital; sacrifício; cor vermelha</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haimatekchusia-bdag\" data-source=\"BDAG\" data-search=\"αἱματεκχυσία haimatekchusia derramamento sangue BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἱματεκχυσία</td><td>Substantivo</td><td>derramamento de sangue</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haimatodes-bdag\" data-source=\"BDAG\" data-search=\"αἱματώδης haimatodes vermelho sangue vermelho escuro vermelho fogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἱματώδης</td><td>Adjetivo</td><td>vermelho-sangue; vermelho-escuro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haimorreo-bdag\" data-source=\"BDAG\" data-search=\"αἱμορροέω haimorroeō sangrar sofrer hemorragia perda sangue BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἱμορροέω</td><td>Verbo</td><td>sangrar; sofrer hemorragia</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aineas-bdag\" data-source=\"BDAG\" data-search=\"Αἰνέας Aineas Eneias Lida paralisia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Αἰνέας</td><td>Nome próprio</td><td>Eneias</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ainesis-bdag\" data-source=\"BDAG\" data-search=\"αἴνεσις ainesis louvor sacrifício louvor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴνεσις</td><td>Substantivo</td><td>louvor</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aineo-bdag\" data-source=\"BDAG\" data-search=\"αἰνέω aineo louvar elogiar Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰνέω</td><td>Verbo</td><td>louvar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ainigma-bdag\" data-source=\"BDAG\" data-search=\"αἴνιγμα ainigma enigma charada comunicação indireta espelho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴνιγμα</td><td>Substantivo</td><td>enigma; modo indireto de comunicação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ainos-bdag\" data-source=\"BDAG\" data-search=\"αἶνος ainos louvor elogio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἶνος</td><td>Substantivo</td><td>louvor</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ainon-bdag\" data-source=\"BDAG\" data-search=\"Αἰνών Ainon Enom Enon João Batista batizava Jordão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Αἰνών</td><td>Nome próprio</td><td>Enom (Enon)</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aix-bdag\" data-source=\"BDAG\" data-search=\"αἴξ aix cabra bode cabrito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴξ</td><td>Substantivo</td><td>cabra</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hairesis-bdag\" data-source=\"BDAG\" data-search=\"αἵρεσις hairesis seita partido escola facção heresia opinião dogma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἵρεσις</td><td>Substantivo</td><td>seita; partido; facção; opinião; dogma</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hairetizo-bdag\" data-source=\"BDAG\" data-search=\"αἱρετίζω hairetizo escolher escolher para si BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἱρετίζω</td><td>Verbo</td><td>escolher; escolher para si</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hairetikos-bdag\" data-source=\"BDAG\" data-search=\"αἱρετικός hairetikos faccioso causador divisão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἱρετικός</td><td>Adjetivo</td><td>faccioso; causador de divisão</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hairetos-bdag\" data-source=\"BDAG\" data-search=\"αἱρετός hairetos desejável preferível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἱρετός</td><td>Adjetivo</td><td>desejável; preferível</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haireo-bdag\" data-source=\"BDAG\" data-search=\"αἱρέω haireo tomar escolher preferir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἱρέω</td><td>Verbo</td><td>tomar; escolher; preferir</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-haima-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἷμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦haîma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+.)\n<span class=\"sense-number\">1.</span> Literalmente, <strong>sangue como componente básico de um organismo, sangue.</strong>\n<strong>a.</strong> De sangue humano: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.34</a> (P. Haupt, “Blood and Water”, AJP 45, 1924, 53–55; F. Dölger, <em>Ac</em> II, 1930, 117 ss.). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅταν ἐκ ξύλου αἷ. στάξῃ\" data-meanings=\"quando sangue gotejar de uma árvore\">ὅταν ἐκ ξύλου αἷ. στάξῃ</span> B 12:1 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4ES.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">4 Esd 5.5</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥύσις αἵματος\" data-meanings=\"fluxo de sangue; hemorragia\">ῥύσις αἵματος</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 15.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">20.18</a>), como enfermidade de mulher, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.43 s.</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πηγὴ τοῦ αἵ.\" data-meanings=\"fonte do sangue\">πηγὴ τοῦ αἵ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.29</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θρόμβοι αἵματος\" data-meanings=\"coágulos de sangue\">θρόμβοι αἵματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.44</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὕδωρ καὶ αἷμα\" data-meanings=\"água e sangue\">ὕδωρ καὶ αἷμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.34</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱμάτιον βεβαμμένον αἵματι\" data-meanings=\"manto tingido de sangue\">ἱμάτιον βεβαμμένον αἵματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19.13</a>.\nEspecialmente como componente principal do corpo humano, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σάρξ\" data-meanings=\"carne\">σάρξ</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σὰρξ καὶ αἷμα\" data-meanings=\"carne e sangue\">σὰρξ καὶ αἷμα</span> = “ser humano”, com forte ênfase no caráter efêmero, na visão limitada e na fraqueza moral (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 14.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">17.31</a>; TestAbr B 13, p. 117, 26 [Stone p. 82]; Fílon, <em>Rer. Div. Her.</em> 57; frequente no rabínico como <bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"בָּשָׂר וָדָם\" data-transliteration=\"bāśār wāḏām\" data-meanings=\"carne e sangue|ser humano\">בָּשָׂר וָדָם</bdi>; Polyaenus 3, 11, 1, de seres humanos em contraste com deuses, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα καὶ σάρκας ἔχοντες\" data-meanings=\"tendo sangue e carne\">αἷμα καὶ σάρκας ἔχοντες</span>; Herm. Fgm. 25, 8b em Stob., <em>Floril.</em> I 461, 12 W. = 510, 27 Sc., de almas <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σαρκὶ καὶ αἵμ. βεβαπτισμέναι\" data-meanings=\"imersas em carne e sangue\">σαρκὶ καὶ αἵμ. βεβαπτισμέναι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.50\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15.50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.12</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κοινωνεῖν αἵματος καὶ σαρκός\" data-meanings=\"participar de sangue e carne\">κοινωνεῖν αἵματος καὶ σαρκός</span> = “participar da natureza humana [dos pais]”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.14</a>.\nO plural <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ αἵματα\" data-meanings=\"os sangues\">τὰ αἵματα</span> (plural nos trágicos; Polyb. 15, 33, 1; LXX; EpArist 88; 90; Ar. 4, 3; Just., Tat.; Mel., <em>P.</em> 50, 368; B-D-F §141, 6) significa <strong>descendência</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξ αἱμάτων γεννηθῆναι\" data-meanings=\"nascer de sangues\">ἐξ αἱμάτων γεννηθῆναι</span> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ θελήματος σαρκός\" data-meanings=\"da vontade da carne\">ἐκ θελήματος σαρκός</span>, oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ θεοῦ\" data-meanings=\"de Deus\">ἐκ θεοῦ</span>) = “dever a descendência à natureza física”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.13</a> (compare Aeschyl., <em>Choëph.</em> 284; Lycophron 1249; inscrições; PLips 28, 16 ss. [381 d.C.]; H. Cadbury, “The Ancient Physiological Notions Underlying J 1:13a, Hb 11:11”, <em>Exp.</em>, 9ª sér., 2, 1924, 430–439). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξ ἑνὸς αἵματος\" data-meanings=\"do sangue de uma só pessoa\">ἐξ ἑνὸς αἵματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.26</a> v.l. (compare Musonius, <em>Ep.</em> 1, 10 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξ αἵματος\" data-meanings=\"de sangue\">ἐξ αἵματος</span>; Jos., <em>Ant.</em> 20, 226).\n<strong>b.</strong> De animais: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">18</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">21 s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">25</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. τράγων\" data-meanings=\"sangue de bodes\">αἷ. τράγων</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Is 1.11</a>) vv. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>; de touros, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; ambos em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">10.4</a> e B 2:5; de bezerros, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζῴων τὸ αἷ.\" data-meanings=\"o sangue de animais\">ζῴων τὸ αἷ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">13.11</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρόσχυσις τοῦ αἵ.\" data-meanings=\"aspersão/derramamento do sangue\">πρόσχυσις τοῦ αἵ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">11.28</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵματι ῥαντισμοῦ\" data-meanings=\"sangue de aspersão\">αἵματι ῥαντισμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">12.24</a>, da oferta de sangue no altar (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.29.12\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 29.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 4.17 ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">8.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">9.9</a>). Seu uso como alimento é proibido (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 3.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">7.26 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">17.10</a>) no decreto de Jerusalém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.20</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">21.25</a>. Representantes dessa interpretação em Haenchen sobre At 15.21 e H. Schoeps, <em>Theol. u. Gesch. d. Judenchristent.</em>, 1949, 191–193; outros, com base numa leitura “ocidental”, interpretam <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπέχεσθαι τ. αἵματος\" data-meanings=\"abster-se do sangue\">ἀπέχεσθαι τ. αἵματος</span> como mandamento para não derramar sangue; compare o uso de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα\" data-meanings=\"sangue; derramamento de sangue\">αἷμα</span> em Paus. Attic. μ, 14; Maximus Tyr. 24, 4k com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σφαγή\" data-meanings=\"matança\">σφαγή</span>; Herodian 2, 6, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 14.25</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα κ. φόνος\" data-meanings=\"sangue e homicídio\">αἷμα κ. φόνος</span>.\n<span class=\"sense-number\">2.</span> Extensão figurada de 1: <strong>sangue como constituinte da vida de uma pessoa, sangue vital.</strong>\n<strong>a.</strong> Como sede da vida (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 17.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 7.2</a>; Jos., <em>Ant.</em> 1, 102): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. ἐκχύννειν\" data-meanings=\"derramar sangue\">αἷ. ἐκχύννειν</span> ou <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκχέειν\" data-meanings=\"derramar\">ἐκχέειν</span> = <strong>matar</strong> (Ésquilo; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 9.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.37.22\" target=\"_blank\" rel=\"noopener noreferrer\">37.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 17.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.17.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1SA.25.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Sm 25.31</a> e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.15</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 13.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.59.7\" target=\"_blank\" rel=\"noopener noreferrer\">Is 59.7</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16.6</a>; AcPl Ha 11, 7. Sangue de Abel e Zacarias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.51</a>; dos galileus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.1</a>; dos profetas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.30</a>; dos santos e profetas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">18.24</a>; dos santos e mártires, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">17.6</a>; dos servos de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">19.2</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">6.10</a>; Pol 2:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. ἀθῷον\" data-meanings=\"sangue inocente\">αἷ. ἀθῷον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.24\" target=\"_blank\" rel=\"noopener noreferrer\">24</a>; GJs 14:1; 23:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. δίκαιον\" data-meanings=\"sangue justo/inocente\">αἷ. δίκαιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.35</a>; AcPl Ha 11, 7. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὔπω μέχρις αἵματος ἀντικατέστητε\" data-meanings=\"ainda não resististes até ao sangue\">οὔπω μέχρις αἵματος ἀντικατέστητε</span> = “até que vosso sangue fosse derramado”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.4</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τιμὴ αἵματος\" data-meanings=\"preço/recompensa de sangue\">τιμὴ αἵματος</span> = recompensa por ato sangrento, homicídio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρὸς αἵματος\" data-meanings=\"campo de sangue\">ἀγρὸς αἵματος</span> = campo comprado com dinheiro de sangue, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">8</a>, diferentemente de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.19</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χωρίον αἵ.\" data-meanings=\"campo de sangue\">χωρίον αἵ.</span> = campo encharcado de sangue. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. ἐκζητεῖν\" data-meanings=\"requerer o sangue\">αἷ. ἐκζητεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.50</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκδικεῖν\" data-meanings=\"vingar\">ἐκδικεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">19.2</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ αἷμα αὐτοῦ ἐφ’ ἡμᾶς\" data-meanings=\"o sangue dele sobre nós\">τὸ αἷμα αὐτοῦ ἐφ’ ἡμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.25</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">23.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">18.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵμα αὐτοῖς δέδωκας πιεῖν\" data-meanings=\"deste-lhes sangue para beber\">αἵμα αὐτοῖς δέδωκας πιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καθαρὸς ἀπὸ τοῦ αἵ. πάντων\" data-meanings=\"limpo do sangue de todos\">καθαρὸς ἀπὸ τοῦ αἵ. πάντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.26</a>. Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵματα\" data-meanings=\"sangues\">αἵματα</span> 1 Cl 18:14 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.16\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.16</a>).\n<strong>b.</strong> <strong>Sangue e vida como sacrifício expiatório</strong>, 1 Cl 55:1. Especialmente do sangue de Jesus (compare Orig., <em>C. Cels.</em> 1, 66, 12 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἐπὶ σταυρῷ προχυθὲν αἷ. Ἰη. Χρ.\" data-meanings=\"o sangue de Jesus Cristo derramado na cruz\">τὸ ἐπὶ σταυρῷ προχυθὲν αἷ. Ἰη. Χρ.</span>) como meio de expiação: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱλαστήριον … ἐν τῷ αὐτοῦ αἵ.\" data-meanings=\"propiciação … em seu sangue\">ἱλαστήριον … ἐν τῷ αὐτοῦ αἵ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.25</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπολύτρωσις διὰ τοῦ αἵ. αὐτοῦ\" data-meanings=\"redenção por seu sangue\">ἀπολύτρωσις διὰ τοῦ αἵ. αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.7</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.14</a> v.l.). Do sacrifício sumo-sacerdotal de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">10.19</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">13.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 1.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">5.9</a>; B 5:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥαντισμὸς αἵ.\" data-meanings=\"aspersão de sangue\">ῥαντισμὸς αἵ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. τοῦ ἀρνίου\" data-meanings=\"sangue do Cordeiro\">αἷ. τοῦ ἀρνίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">12.11</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμνοῦ\" data-meanings=\"do cordeiro\">ἀμνοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.19</a>. Como meio de libertação da culpa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.9</a>; 1 Cl 7:4; 12:7; 21:6; 49:6. Daí <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πιστεύειν εἰς τὸ αἷ. Χρ.\" data-meanings=\"crer no sangue de Cristo\">πιστεύειν εἰς τὸ αἷ. Χρ.</span> ISm 6:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. τῆς διαθήκης\" data-meanings=\"sangue da aliança\">αἷ. τῆς διαθήκης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.20</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.24.8\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 24.8</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">10.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">13.20</a> (TestBenj 3:8; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.24.8\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 24.8</a>). Especialmente nas palavras de instituição da Eucaristia (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διαθήκη\" data-meanings=\"aliança\">διαθήκη</span> 2 e fim), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11.25</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">10.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.53\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.53–55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 5.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῦ αἵ. τοῦ κυρίου\" data-meanings=\"do sangue do Senhor\">τοῦ αἵ. τοῦ κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11.27</a>. Da associação na Eucaristia, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ποτήριον εἰς ἕνωσιν τοῦ αἵ. αὐτοῦ\" data-meanings=\"cálice para união com seu sangue\">ποτήριον εἰς ἕνωσιν τοῦ αἵ. αὐτοῦ</span> IPhld 4.\nDescrito como o meio pelo qual Deus adquiriu a assembleia/comunidade cristã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.28</a> (o sangue parece ser o de Jesus, possessão preciosa de Deus e, portanto, expressão de generosidade extraordinária; sobre <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵ. τοῦ ἰδίου\" data-meanings=\"sangue do seu próprio\">αἵ. τοῦ ἰδίου</span> nessa passagem, veja Danker, <em>Benefactor</em> 335–336; diferentemente C. DeVine, “The Blood of God”, CBQ 9, 1947, 381–408; também J. Lambrecht, “Paul’s Farewell-Address at Miletus [Acts 20:17–38]”, em <em>Les Actes des Apôtres</em>, ed. J. Kremer, 1979, 322 n. 54); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.13</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰρηνοποιήσας διὰ τοῦ αἵ. τοῦ σταυροῦ αὐτοῦ\" data-meanings=\"fazendo a paz pelo sangue de sua cruz\">εἰρηνοποιήσας διὰ τοῦ αἵ. τοῦ σταυροῦ αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.20</a>. O amor é descrito como sangue de Jesus, ITr 8:1; IRo 7:3; compare ISm 1:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷ. θεοῦ\" data-meanings=\"sangue de Deus\">αἷ. θεοῦ</span> IEph 1:1 (veja Hdb. e At 20.28 acima). — F. Rüsche, <em>Blut, Leben u. Seele</em>, 1930; A. Anwander, “D. Blut in rel.-gesch. Schau”, TGl 26, 1934, 414–427; O. Schmitz, <em>D. Opferanschauung d. späteren Judentums u. d. Opferaussagen d. NT</em>, 1910; A. Scott, <em>Christianity acc. to St. Paul</em>, 1927, 85 ss.; J. Schneider, <em>D. Passionsmystik d. Pls</em>, 1929, 28 ss.; 120 ss.; H. Windisch, Hdb., excursus sobre Hb 9.22 (2ª ed. 1931; bibliografia ali e J. Waszink, RAC II 459–473).\n<span class=\"sense-number\">3.</span> <strong>A cor vermelha apocalíptica, cuja aparição no céu indica desastre, sangue.</strong> (M. Müller, ZNW 8, 1907, 290 ss.; E. Wunderlich, <em>D. Bed. d. roten Farbe im Kult d. Griechen u. Römer</em>, 1925.) Com fogo e fumaça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.19</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jl 3.3</a>). Assim o mundo terminará <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δι’ αἵματος καὶ πυρός\" data-meanings=\"por sangue e fogo\">δι’ αἵματος καὶ πυρός</span> Hv 4, 3, 3. Com fogo e granizo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8.7</a>. Da cor da água, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">11.6</a> (Jos., <em>Ant.</em> 3, 17: água transformada em sangue é imprópria para beber); compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">16.3 s.</a>. Da cor da lua, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.20</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jl 3.4</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6.12</a>. A figura “sangue da uva” (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.49.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 49.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.32.14\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 32.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.39.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 39.26</a>) é usada apocalipticamente: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξῆλθεν αἷ. ἐκ τῆς ληνοῦ\" data-meanings=\"saiu sangue do lagar\">ἐξῆλθεν αἷ. ἐκ τῆς ληνοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.20</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.63.1\" target=\"_blank\" rel=\"noopener noreferrer\">Is 63.1–3</a>). Sobre o papel do sangue com outros presságios terríveis, compare Appian, <em>Bell. Civ.</em> 2, 36 §144; 4, 4 §14. — Em geral, L. Morris, JTS n.s. 3, 1952, 216–227; L. Dewar, ibid. 4, 1953, 204–208. — B. 206. DELG. M-M. TW. Sv.\n</p></section></article><article id=\"entry-haimatekchusia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματεκχυσία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦haimatekchusía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(De <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα\" data-meanings=\"sangue\">αἷμα</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκχέω\" data-meanings=\"derramar\">ἐκχέω</span>; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα\" data-meanings=\"sangue\">αἷμα</span> 2a.) <strong>Derramamento ou efusão de sangue</strong> (encontrado apenas em escritores cristãos, por exemplo Tat. 23, 2; cronistas bizantinos em Psaltes p. 349; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔκχυσις αἵματος\" data-meanings=\"derramamento de sangue\">ἔκχυσις αἵματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1KI.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Rs 18.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.27.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 27.15</a>; Charax de Pérgamo [sécs. II/III d.C.], 103 Fgm. 5 Jac.): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χωρὶς αἱ. οὐ γίνεται ἄφεσις\" data-meanings=\"sem derramamento de sangue não há perdão\">χωρὶς αἱ. οὐ γίνεται ἄφεσις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.22</a> — o referente é o sangue oferecido no altar; veja T. Thornton, JTS n.s. 15, 1964, 63–65, com referência a passagens como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 4.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">18</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">25</a> e outras. — TW.\n</p></section></article><article id=\"entry-haimatodes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱματώδης</h1><div class=\"entry-meta\"><span class=\"greek\">ες</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦haimatṓdēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα\" data-meanings=\"sangue\">αἷμα</span> + <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"-ώδης\" data-meanings=\"sufixo com sentido de semelhante a / caracterizado por\">-ώδης</span>; Tucídides e outros.) <strong>Vermelho-sangue</strong> (escólio a Nicandro, <em>Ther.</em> 228; Cat. Cod. Astr. VIII/2 p. 174, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἄρες αἱ.\" data-meanings=\"Ares vermelho-sangue\">Ἄρες αἱ.</span>), isto é, <strong>vermelho-escuro</strong>, Hv 4, 1, 10 (como cor apocalíptica juntamente com preto, amarelo e branco; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα\" data-meanings=\"sangue\">αἷμα</span> 3); com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πυροειδής\" data-meanings=\"semelhante ao fogo; cor de fogo\">πυροειδής</span> (q.v.), <strong>vermelho como fogo</strong>, isto é, vermelho-claro, 4, 3, 3.\n</p></section></article><article id=\"entry-haimorreo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱμορροέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦haimorroéō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Hipócrates e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 15.33</a>) <strong>Experimentar perda de sangue, sangrar, sofrer de hemorragia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.20</a>; AcPl BMM verso 17; <em>Acta Pilati</em> Ea 7 (ASyn. 95, 90). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥέω\" data-meanings=\"fluir\">ῥέω</span> 971. M-M.\n</p></section></article><article id=\"entry-aineas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰνέας</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Ainéas⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Literatura; inscrições [por exemplo ISyriaW 1929; 2238; também da Palestina: SEG VIII, 255 — 112/111 a.C.]; papiros [Preisigke, <em>Namenbuch</em>].) <strong>Eneias</strong>, em Lida, curado da paralisia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.33 s.</a>. — DDD s.v. Aeneas.\n</p></section></article><article id=\"entry-ainesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴνεσις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aínesis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Philod., <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρρ.\" data-meanings=\"abreviação do título de obra conforme citada pelo BDAG\">παρρ.</span> col. 8a, p. 48 [10 Oliv.]; LXX; Fílon, <em>Spec. Leg.</em> 1, 224; Iren. 1, 14, 8 [Harv. I 143, 10].) <strong>Louvor.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναφέρειν θυσίαν αἰνέσεως\" data-meanings=\"oferecer sacrifício de louvor\">ἀναφέρειν θυσίαν αἰνέσεως</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.15</a> (compare <bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"זֶבַח תּוֹדָה\" data-transliteration=\"zeḇaḥ tôḏâ\" data-meanings=\"sacrifício de ação de graças|sacrifício de louvor\">זֶבַח תּוֹדָה</bdi> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 7.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>); compare 1 Cl 35:12 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.49.23\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 49.23</a>); 52:3 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.49.14\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 49.14</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναγγέλλειν τὴν αἴ. τινος\" data-meanings=\"proclamar o louvor de alguém\">ἀναγγέλλειν τὴν αἴ. τινος</span> 1 Cl 18:15 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.17\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.17</a>). Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰνέω\" data-meanings=\"louvar\">αἰνέω</span>.\n</p></section></article><article id=\"entry-aineo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰνέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ainéō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. αἰνέσω; 1 aor. ᾔνεσα</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Louvar</strong> (Homero e outros; LXX; TestSol 12:5; TestAbr; Just. A ideia primária é “expressar aprovação”; compare IG IX/1, 119, 8). Em nossa literatura, usado apenas do louvor a Deus (Diog. L. 1, 39; muito frequente na LXX; TestAbr B 14, p. 119, 2 [Stone p. 86]; Just., <em>A</em> I, 13, 1; <em>D.</em> 106, 1; PGM 4, 1146): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰ. τὸν θεόν\" data-meanings=\"louvar a Deus\">αἰ. τὸν θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">19.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.53\" target=\"_blank\" rel=\"noopener noreferrer\">24.53</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">3.8 s.</a>; compare MPol 14:3. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν κύριον\" data-meanings=\"o Senhor\">τὸν κύριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.11</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.116.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 116.1</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῷ θεῷ ἡμῶν\" data-meanings=\"ao nosso Deus\">τῷ θεῷ ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19.5</a> — o dativo corresponde ao hebraico <bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"לְ\" data-transliteration=\"lə\" data-meanings=\"a|para\">לְ</bdi> com formas de <bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"הוֹדָה\" data-transliteration=\"hôḏâ\" data-meanings=\"dar graças|louvar\">הוֹדָה</bdi> e <bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"הִלֵּל\" data-transliteration=\"hillēl\" data-meanings=\"louvar\">הִלֵּל</bdi>, por exemplo na LXX em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 20.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1CH.16.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cr 16.36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cr 5.13</a>; B-D-F §187, 4; compare B 7:1. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐλογεῖν\" data-meanings=\"bendizer; louvar\">εὐλογεῖν</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 5.23</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.53</a> v.l. (veja G. Kilpatrick em <em>Essays in Memory of G. H. C. Macgregor</em>, 1965, 19). Do louvor de deuses por politeístas, Dg 2:7 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDG.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jz 16.24</a> A; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 5.23</a>). Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶνος\" data-meanings=\"louvor\">αἶνος</span>. — M-M. TW.\n</p></section></article><article id=\"entry-ainigma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴνιγμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aínigma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Píndaro, Ésquilo e outros; LXX, Fílon; Jos., <em>C. Ap.</em> 1, 114 s.; SibOr 3, 812.)\n<span class=\"sense-number\">1.</span> Literalmente, <strong>aquilo que exige perspicácia especial para ser compreendido porque é expresso de maneira enigmática, enigma, charada</strong>, PtK 4 p. 15, 31. Alguns preferem este sentido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 13.12</a>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βλέπομεν δι’ ἐσόπτρου ἐν αἰνίγματι\" data-meanings=\"vemos por meio de um espelho em enigma\">βλέπομεν δι’ ἐσόπτρου ἐν αἰνίγματι</span> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν αἰν.\" data-meanings=\"em enigma\">ἐν αἰν.</span> como Athen. 452a; REB: “reflexos enigmáticos”; NRSV: “de modo obscuro” [= indistintamente], mas a nota marginal traz “em um enigma”). Hugedé pode oferecer explicação melhor; veja 2 abaixo.\n<span class=\"sense-number\">2.</span> <strong>Modo indireto de comunicação.</strong> No contexto da imagem do espelho, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"αἴνιγμα\">ἀ.</span> significa <strong>imagem indireta</strong>, e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν αἰνίγματι\" data-meanings=\"em enigma\">ἐν αἰνίγματι</span> funciona como expressão idiomática com o sentido <strong>indiretamente</strong>. Assim, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βλέπομεν δι’ ἐσόπτρου ἐν αἰνίγματι\" data-meanings=\"vemos por meio de um espelho em enigma\">βλέπομεν δι’ ἐσόπτρου ἐν αἰνίγματι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 13.12</a> dá o sentido “vemos por reflexão, como num espelho”, com ênfase na expectativa de um encontro pessoal direto. Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 12.8</a>, da comunicação direta em oposição à oblíqua. Plut., <em>Mor.</em> 382a, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. τοῦ θείου\" data-meanings=\"enigma do divino\">αἴ. τοῦ θείου</span>, refere-se a coisas inanimadas ou incorpóreas, como números, enquanto “espelhos” ou “modelos” para a compreensão de assuntos divinos. Compare <em>Mor.</em> 12d, de máximas pitagóricas que comunicam <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰνίγμασιν\" data-meanings=\"por enigmas\">αἰνίγμασιν</span> = falam por circunlóquios, isto é, “ambiguamente” ou “com duplo sentido”; 370f contrasta as apresentações anteriores de Platão <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δι’ αἰνιγμῶν οὐδὲ συμβολικῶς\" data-meanings=\"por enigmas, nem simbolicamente\">δι’ αἰνιγμῶν οὐδὲ συμβολικῶς</span> com seu uso posterior de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κύρια ὀνόματα\" data-meanings=\"termos próprios; expressões diretas\">κύρια ὀνόματα</span>. Sobre a imagem do espelho, compare <em>Mor.</em> 672e. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴνιγμα\" data-meanings=\"enigma\">αἴνιγμα</span> = “insinuação”, Sallust. c. 6 p. 12, 10. — N. Hugedé, <em>La Métaphore du miroir dans 1 et 2 Cor</em>, 1957; outra bibliografia s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor\">ἀγάπη</span> 1aα e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔσοπτρον\" data-meanings=\"espelho\">ἔσοπτρον</span>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶνος\" data-meanings=\"louvor; narrativa\">αἶνος</span>. TW. Sv.\n</p></section></article><article id=\"entry-ainos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἶνος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aînos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero e outros; inscrições, LXX [PsSol 3:1 por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καινός\" data-meanings=\"novo\">καινός</span>]. Em vários sentidos, inclusive “narrativa, decreto, elogio”; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰνέω\" data-meanings=\"louvar\">αἰνέω</span>.) <strong>Louvor.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶνον διδόναι τῷ θεῷ\" data-meanings=\"dar louvor a Deus\">αἶνον διδόναι τῷ θεῷ</span>, “louvar a Deus”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.43</a>; 2 Cl 1:5; 9:10. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καταρτίζεσθαι αἶνον\" data-meanings=\"produzir/formar louvor para si\">καταρτίζεσθαι αἶνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.16</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 8.3</a>). — DELG. M-M. TW. Sv.\n</p></section></article><article id=\"entry-ainon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰνών</h1><div class=\"entry-meta\"><span class=\"article greek\">ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Ainṓn⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Enom (Enon)</strong>, lugar onde João Batista estava batizando, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.23</a>. A antiga tradição eclesiástica (Eus., <em>Onom.</em> p. 41) o situa no vale do Jordão, cerca de 13 km ao sul de Citópolis (Bete-Seã). — T. Zahn, NKZ 18, 1907, 593–608; C. Kopp, <em>Holy Places of the Gospels</em>, 1963, 129–137; veja também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Σαλίμ\" data-meanings=\"Salim\">Σαλίμ</span>.\n</p></section></article><article id=\"entry-aix-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴξ</h1><div class=\"entry-meta\"><span class=\"greek\">αἰγός, ὁ, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aíx⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Cabra</strong> (Homero+; inscrições, papiros, LXX; TestJob 15:4 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐρίφους αἰγῶν\" data-meanings=\"cabritos de cabras\">ἐρίφους αἰγῶν</span>; GrBar 2:3; Fílon, <em>Omn. Prob. Lib.</em> 30; Jos., <em>Ant.</em> 6, 217; 295; TestZeb 4:9; SibOr 3, 627; Just.). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔριφος ἐξ αἰγῶν\" data-meanings=\"cabrito dentre as cabras\">ἔριφος ἐξ αἰγῶν</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.38.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 38.20</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.29</a> D. — B. 165. DELG.\n</p></section></article><article id=\"entry-hairesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἵρεσις</h1><div class=\"entry-meta\"><span class=\"greek\">έσεως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦haíresis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Ésquilo, Heródoto e outros; termo usado no grego helenístico especialmente com referência a preferência política ou lealdade de grupo, como em SIG 675, 28 [séc. II a.C.], onde <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵ.\" data-meanings=\"αἵρεσις\">αἵ.</span> é usado <em>in bonam partem</em>, uso comum em correspondência diplomática: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γίνωνται δὲ καὶ ἄλλοι ζηλωταὶ τῆς αὐτῆς αἱρέσεως\" data-meanings=\"que também outros se tornem zelosos da mesma orientação\">γίνωνται δὲ καὶ ἄλλοι ζηλωταὶ τῆς αὐτῆς αἱρέσεως</span>.)\n<span class=\"sense-number\">1.</span> <strong>Grupo que sustenta princípios distintivos, seita, partido, escola, facção.</strong> De escolas filosóficas: Diod S 2, 29, 6; Dionys. Hal., <em>Comp. Verb.</em> 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τ. Στωϊκῆς αἱ.\" data-meanings=\"da escola estoica\">τ. Στωϊκῆς αἱ.</span>; Diog. L. 1, 18 e 19 e outros; Iambl., <em>Vi. Pyth.</em> 34, 241; Orig., <em>C. Cels.</em> 4, 45, 32; H. Diels, <em>Doxographi Graeci</em>, 1879, índice; Aristóbulo em Eus., <em>PE</em> 13, 12, 10 = Denis 224, col. 1, 13; Holladay 196; veja Nägeli 51; Poland 154.\n<strong>a.</strong> Dos saduceus, como seita, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.17</a> (Jos., <em>Ant.</em> 13, 171; 20, 199). Dos fariseus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.5</a> (Jos., <em>Vi.</em> 10; 12; 191 e outros). Estes últimos são descritos como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἀκριβεστάτη αἵ. τῆς ἡμετέρας θρησκείας\" data-meanings=\"a seita mais rigorosa de nossa religião\">ἡ ἀκριβεστάτη αἵ. τῆς ἡμετέρας θρησκείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.5</a>. Dos cristãos, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵρεσις τῶν Ναζωραίων\" data-meanings=\"seita dos nazarenos\">αἵρεσις τῶν Ναζωραίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 24.5</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">14</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.22\" target=\"_blank\" rel=\"noopener noreferrer\">28.22</a>. Os três últimos exemplos tendem para o sentido b.\n<strong>b.</strong> No sentido posterior, <strong>seita herética</strong> (Iren. 1, 11, 1 [Harv. I 98, 5]; Orig., <em>C. Cels.</em> 5, 54, 9), IEph 6:2; ITr 6:1; Epil Mosq 1. Compare também o <em>agraphon</em> de Justino, <em>Trypho</em> 35, em J. Jeremias, <em>Unknown Sayings</em>, 59–61. Em geral: W. Bauer, <em>Rechtgläubigkeit u. Ketzerei im ältesten Christentum</em>, 1934, 2ª ed. com suplemento de G. Strecker, 1964; M. Meinertz, “Σχίσμα und αἵρεσις im NT”, BZ 1, 1957, 114–118.\n<strong>c.</strong> Com conotação negativa, <strong>dissensão, facção</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5.20</a>.\n<span class=\"sense-number\">2.</span> <strong>Aquilo que distingue o pensamento de um grupo, opinião, dogma.</strong> (Fílon, <em>Plant.</em> 151 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κυνικὴ αἵ.\" data-meanings=\"opinião/doutrina cínica\">κυνικὴ αἵ.</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱ. ἀπωλείας\" data-meanings=\"opiniões destrutivas\">αἱ. ἀπωλείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.1</a> — talvez também no sentido 1b. — <strong>Modo de pensar</strong> (UPZ 20, 26 [163 a.C.]; 144, 10 e outros): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵ. ἔχειν\" data-meanings=\"ter um modo de pensar\">αἵ. ἔχειν</span> Hs 9, 23, 5; “inclinação” também é possível (GDI 2746, 14; 2800, 7, ambos de Delfos). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱρέω\" data-meanings=\"escolher\">αἱρέω</span>. M-M. TW. Sv.\n</p></section></article><article id=\"entry-hairetizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρετίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hairetízō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. αἱρετιῶ; 1 aor. ᾑρέτισα; pf. ᾑρέτικα</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Hipócrates e outros; SIG 1042, 2; UPZ 109, 4 [98 a.C.]; talvez Babrius 61, 5 [L-P.].) Ativo, <strong>escolher</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.18</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/HAG.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ag 2.23</a>; talvez “adotar”, como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1CH.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cr 28.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/MAL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ml 3.17</a>; Kaibel 252). — Médio (desde Ctesias, 688 Fgm. 13, 10 Jac.; LXX), <strong>escolher para si</strong>, com infinitivo seguinte (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 9.30</a>), 2 Cl 14:1. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱρέω\" data-meanings=\"escolher\">αἱρέω</span>. M-M. TW.</p></section></article><article id=\"entry-hairetikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρετικός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hairetikós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ps.-Pla., <em>Definit.</em> 412a; Aelian, <em>NA</em> 6, 59; Hierocles Stoic. [sécs. I/II d.C.], <em>Eth.</em> 9, 5; aqui 7 e Diog. L. 7, 126 também o advérbio; substantivado no plural <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ αἱ.\" data-meanings=\"os facciosos\">οἱ αἱ.</span> Iren. 5, 13, 2 [Harv. II 356, 8] e outros.) <strong>Relativo a causar divisões, faccioso, causador de divisão</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνθρωπος αἱ.\" data-meanings=\"pessoa facciosa; causadora de divisão\">ἄνθρωπος αἱ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3.10</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἵρεσις\" data-meanings=\"seita; facção\">αἵρεσις</span> 1b, c). — TW.</p></section></article><article id=\"entry-hairetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρετός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hairetós⟧</span><span class=\"separator\">·</span><span class=\"greek\">comp. αἱρετώτερος</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Desejável</strong> (Heródoto e outros; LXX; Ath., <em>R.</em> 75, 23; Sb 6996, 25 [séc. II d.C.]): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱρετώτερον ἦν αὐτοῖς\" data-meanings=\"teria sido mais desejável/preferível para eles\">αἱρετώτερον ἦν αὐτοῖς</span> com infinitivo seguinte (X., <em>Cyr.</em> 3, 3, 51; Diod S 14, 45, 3; Polyaenus 4, 6, 6; Aesop, <em>Fab.</em> 261 P. = 273 H.; 168 H-H.; 223 Ch.; compare Sextus 362), “teria sido melhor para eles”, Hv 4, 2, 6. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱρέω\" data-meanings=\"escolher\">αἱρέω</span>.</p></section></article><article id=\"entry-haireo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἱρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hairéō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. méd. αἱρήσομαι; 2 aor. εἱλόμην e εἱλάμην</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Formas em -α- em Tdf., W-H, M., Bov., N.; formas em -ο- em V., t.r.; veja também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναιρέω\" data-meanings=\"tirar; matar\">ἀναιρέω</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξαιρέω\" data-meanings=\"tirar; livrar\">ἐξαιρέω</span>; Homero+.) <span class=\"sense-number\">1.</span> Ativo, <strong>tomar</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καρπὸν αἱρῶν\" data-meanings=\"tomando/colhendo fruto\">καρπὸν αἱρῶν</span> Dg 12:8 (texto incerto; veja Bihlmeyer ad loc.). <span class=\"sense-number\">2.</span> Médio — assim exclusivamente no NT, Tat. e Ath. —, <strong>escolher</strong> (veja Nägeli 19 s.). Com duplo acusativo (Hdt. 1, 96; Jos., <em>Ant.</em> 9, 106), Hs 5, 6, 6. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινὰ εἴς τι\" data-meanings=\"alguém para algo\">τινὰ εἴς τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2.13</a>. Com acusativo, <strong>preferir</strong> (Diod S 17, 29, 3; 17, 48, 2; Jos., <em>Bell.</em> 6, 330), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.22</a>; semelhantemente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μᾶλλον αἱ.\" data-meanings=\"preferir antes\">μᾶλλον αἱ.</span> com infinitivo seguinte e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤ\" data-meanings=\"do que\">ἤ</span> com infinitivo (Pla., <em>Ap.</em> 38e; Diod S 11, 11, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μᾶλλον εἵλοντο τελευτᾶν ἢ ζῆν\" data-meanings=\"preferiram morrer a viver\">μᾶλλον εἵλοντο τελευτᾶν ἢ ζῆν</span>; <em>Περὶ ὕψους</em> 33, 5; Appian, <em>Bell. Civ.</em> 4, 117 §491), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.25</a>. — B. 743. DELG. M-M. TW.</p></section></article>"};
